import os
import json

search_root = "/Users/jsriverab/.gemini/antigravity/brain"
found_transcripts = []

for root, dirs, files in os.walk(search_root):
    for file in files:
        if file == "transcript_full.jsonl":
            path = os.path.join(root, file)
            # check if it contains SITE_META
            try:
                with open(path, "r", encoding="utf-8") as f:
                    for line in f:
                        if "SITE_META" in line:
                            print(f"FOUND IN: {path}")
                            found_transcripts.append(path)
                            break
            except Exception as e:
                pass

print(f"Done search. Found in {len(found_transcripts)} transcripts.")
